(5194984, 754338, 32736, '<td valign="top">Too fuzzy for me.</td>', 'Too fuzzy for me.', '2009-01-16 09:54:30.000000', NULL, 1),
(5194985, 755000, 15711, '<td valign="top">Godot? I like this but have a hard time deciding where to rest my eyes.  On the men and dog, or to the left with the building.  I might''ve done either a study of the human and canine sense of this photo, or concentrated on the architecture.</td>', 'Godot? I like this but have a hard time deciding where to rest my eyes.  On the men and dog, or to the left with the building.  I might''ve done either a study of the human and canine sense of this photo, or concentrated on the architecture.', '2009-01-16 09:54:32.000000', NULL, 1),
(5194986, 754762, 63398, '<td valign="top">Nice composition, and I like the sun blast. 7</td>', 'Nice composition, and I like the sun blast. 7', '2009-01-16 09:54:36.000000', NULL, 1),
(5194990, 756314, 15711, '<td valign="top">Maybe a touch harsh on the light at the top of her hair, but a worthy candid portrait.</td>', 'Maybe a touch harsh on the light at the top of her hair, but a worthy candid portrait.', '2009-01-16 09:55:20.000000', NULL, 1),
(5194991, 755197, 67152, '<td valign="top">the layers created by the colors is outstanding - the rich green valley, the purple mountains, and the orange and magenta sky - it creates a rainbow without rain</td>', 'the layers created by the colors is outstanding - the rich green valley, the purple mountains, and the orange and magenta sky - it creates a rainbow without rain', '2009-01-16 09:55:21.000000', NULL, 1),
(5194993, 756466, 79955, '<td valign="top">Nice,  crop a tad too tight on the right. 7</td>', 'Nice,  crop a tad too tight on the right. 7', '2009-01-16 09:55:33.000000', NULL, 1),
(5194996, 755482, 63398, '<td valign="top">Excellent macro.....terrific colour &amp; composition. My only niggling thing would be that I''d like to see just the teensiest bit more sharpness. Lovely image, nonetheless. 7</td>', 'Excellent macro.....terrific colour & composition. My only niggling thing would be that I''d like to see just the teensiest bit more sharpness. Lovely image, nonetheless. 7', '2009-01-16 09:55:55.000000', NULL, 1);
