(5195025, 756106, 15711, '<td valign="top">I love the simplicity. Nice composition and the velvety green bokeh is delicious.</td>', 'I love the simplicity. Nice composition and the velvety green bokeh is delicious.', '2009-01-16 10:03:00.000000', NULL, 1),
(5195026, 756637, 35357, '<td valign="top">Wow! Gorgeous!</td>', 'Wow! Gorgeous!', '2009-01-16 10:03:05.000000', NULL, 1),
(5195027, 754611, 15711, '<td valign="top">Zodiac?  That''s a new one to me.  Love the purple and the perspective. Great composition and sky.</td>', 'Zodiac?  That''s a new one to me.  Love the purple and the perspective. Great composition and sky.', '2009-01-16 10:03:22.000000', NULL, 1),
