(5195030, 754457, 32736, '<td valign="top">Need more light.</td>', 'Need more light.', '2009-01-16 10:03:58.000000', NULL, 1),
(5195034, 756378, 32736, '<td valign="top">Love the lighting.</td>', 'Love the lighting.', '2009-01-16 10:04:50.000000', NULL, 1),
(5195037, 755900, 32736, '<td valign="top">This is too dark, but I like the angle.</td>', 'This is too dark, but I like the angle.', '2009-01-16 10:05:12.000000', NULL, 1),
