(5199886, 754658, 30454, '<td valign="top">WOW, excellent cloud, nice colors. The girl in the photo tells a bunch of stories. Nice one. Good Luck.</td>', 'WOW, excellent cloud, nice colors. The girl in the photo tells a bunch of stories. Nice one. Good Luck.', '2009-01-17 17:14:15.000000', NULL, 1),
(5199888, 754453, 9576, '<td valign="top">Great capture here 10</td>', 'Great capture here 10', '2009-01-17 17:14:55.000000', NULL, 1),
