INSERT INTO comments ("id", "image_id", "commenter_id", "raw_comment", "comment", "date", "edited", "made_during_challenge") VALUES
(5199945, 756604, 76335, '<td valign="top">Great moment and I like the angle. Would like to ahve seen more of his face.</td>', 'Great moment and I like the angle. Would like to ahve seen more of his face.', '2009-01-17 17:30:44.000000', NULL, 1),
(5199960, 754484, 81362, '<td valign="top">Sharp while retaining huge sense of motion. Needs to be in a photography textbook as a great example of "freezing" motion to put emphasis on it. Tones balance well, and this dynamic image keeps the eye busy for a long time.</td>', 'Sharp while retaining huge sense of motion. Needs to be in a photography textbook as a great example of "freezing" motion to put emphasis on it. Tones balance well, and this dynamic image keeps the eye busy for a long time.', '2009-01-17 17:34:04.000000', NULL, 1),
(5199964, 756729, 81362, '<td valign="top">Love the juxtaposition. With the person being far from horizontal, consider a portrait crop to remove the For Rent sign, but keep a good part of that intersting red door.</td>', 'Love the juxtaposition. With the person being far from horizontal, consider a portrait crop to remove the For Rent sign, but keep a good part of that intersting red door.', '2009-01-17 17:36:28.000000', NULL, 1),
(5199967, 756700, 81362, '<td valign="top">I like the macro approach, with detail near the edge of the contrast between orange tones and yellow-greens.</td>', 'I like the macro approach, with detail near the edge of the contrast between orange tones and yellow-greens.', '2009-01-17 17:37:28.000000', NULL, 1),
(5199970, 756628, 81362, '<td valign="top">Ouch. Makes me wince. Powerful capture here.</td>', 'Ouch. Makes me wince. Powerful capture here.', '2009-01-17 17:38:45.000000', NULL, 1),
(5199984, 754744, 81362, '<td valign="top">Nice lines and lighting. Love all the sense of purity, which could be perfect if done over without the diaper. 7.</td>', 'Nice lines and lighting. Love all the sense of purity, which could be perfect if done over without the diaper. 7.', '2009-01-17 17:44:39.000000', NULL, 1),
(5199990, 756728, 76335, '<td valign="top">Great scene. Sharpening is a little obvious where there mountain meets the sky.</td>', 'Great scene. Sharpening is a little obvious where there mountain meets the sky.', '2009-01-17 17:51:33.000000', NULL, 1),
(5199993, 755935, 76335, '<td valign="top">Framing is terrific. Good placement of the bird and negative space.</td>', 'Framing is terrific. Good placement of the bird and negative space.', '2009-01-17 17:52:08.000000', NULL, 1),
(5199996, 754955, 76335, '<td valign="top">I like the curvature of the ground, and the way it seems to be swept in the spiral clouds.</td>', 'I like the curvature of the ground, and the way it seems to be swept in the spiral clouds.', '2009-01-17 17:54:05.000000', NULL, 1),
(5199998, 755096, 76335, '<td valign="top">Negative? Nicely done.</td>', 'Negative? Nicely done.', '2009-01-17 17:55:08.000000', NULL, 1),
(5200007, 755133, 70514, '<td valign="top">Such beautiful eyes, smile and life.  The b/w is gorgeous, it really compliments your title.</td>', 'Such beautiful eyes, smile and life.  The b/w is gorgeous, it really compliments your title.', '2009-01-17 18:02:25.000000', NULL, 1),
(5200008, 754450, 70514, '<td valign="top">I kind of like the choice of duotone.  It''s different and interesting.  Wish the crop excluded the sky though.</td>', 'I kind of like the choice of duotone.  It''s different and interesting.  Wish the crop excluded the sky though.', '2009-01-17 18:03:28.000000', NULL, 1),
(5200010, 756705, 70514, '<td valign="top">Wow! Sad, poignant, and the green bg seems so incongruent to the subject, but it seems to really work for me.</td>', 'Wow! Sad, poignant, and the green bg seems so incongruent to the subject, but it seems to really work for me.', '2009-01-17 18:04:08.000000', NULL, 1),
(5200016, 754579, 70514, '<td valign="top">That''s an amzing and beautiful reflection.</td>', 'That''s an amzing and beautiful reflection.', '2009-01-17 18:10:34.000000', NULL, 1),
(5200017, 756408, 70514, '<td valign="top">Very funny and amazing detail.  I love the greens as well.</td>', 'Very funny and amazing detail.  I love the greens as well.', '2009-01-17 18:11:04.000000', NULL, 1),
(5200018, 754540, 70514, '<td valign="top">A beautiful picture of a flame, and nicely done in a glass to boot.  I love the warm tones, the exposure is perfect.</td>', 'A beautiful picture of a flame, and nicely done in a glass to boot.  I love the warm tones, the exposure is perfect.', '2009-01-17 18:12:16.000000', NULL, 1),
(5200019, 756428, 70514, '<td valign="top">Feels like a great big hug!  Lovely!</td>', 'Feels like a great big hug!  Lovely!', '2009-01-17 18:12:30.000000', NULL, 1),
(5200020, 755467, 70514, '<td valign="top">Wonderful processing to accentuate the subject.</td>', 'Wonderful processing to accentuate the subject.', '2009-01-17 18:13:03.000000', NULL, 1),
(5200021, 754712, 70514, '<td valign="top">I love the perspective, her hair moving, and the expression.  Beautiful girl.</td>', 'I love the perspective, her hair moving, and the expression.  Beautiful girl.', '2009-01-17 18:13:37.000000', NULL, 1),
(5200023, 756753, 70514, '<td valign="top">Wonderful perspective and capture!  Kind of sends shivers up my spine.</td>', 'Wonderful perspective and capture!  Kind of sends shivers up my spine.', '2009-01-17 18:14:33.000000', NULL, 1),
(5200024, 755257, 70514, '<td valign="top">Stunning and beautiful.</td>', 'Stunning and beautiful.', '2009-01-17 18:14:51.000000', NULL, 1),
(5200025, 755898, 70514, '<td valign="top">The colors are gorgeous.  Love the composition and softness of the water.</td>', 'The colors are gorgeous.  Love the composition and softness of the water.', '2009-01-17 18:15:15.000000', NULL, 1),
(5200028, 755812, 70514, '<td valign="top">A beautiful silhouette that has wonderful emotion felt.</td>', 'A beautiful silhouette that has wonderful emotion felt.', '2009-01-17 18:16:07.000000', NULL, 1),
(5200033, 755662, 70514, '<td valign="top">I really like this.  It''s interesting.  I dunno, sorry I have nothing else.  But I just like it.</td>', 'I really like this.  It''s interesting.  I dunno, sorry I have nothing else.  But I just like it.', '2009-01-17 18:24:33.000000', NULL, 1),
(5200035, 754561, 70514, '<td valign="top">Clowns creep me out, but I must say, I like the crop here.</td>', 'Clowns creep me out, but I must say, I like the crop here.', '2009-01-17 18:25:31.000000', NULL, 1),
(5200038, 755643, 70514, '<td valign="top">Absolutely beautiful, I especially like the conversion, as well as the one bird lifting up with his wings flapping, and the light on him.  Beautiful capture.</td>', 'Absolutely beautiful, I especially like the conversion, as well as the one bird lifting up with his wings flapping, and the light on him.  Beautiful capture.', '2009-01-17 18:26:35.000000', NULL, 1),
(5200046, 754386, 70514, '<td valign="top">You captured all of her beauty in one shot.  Gorgeous conversion as well.</td>', 'You captured all of her beauty in one shot.  Gorgeous conversion as well.', '2009-01-17 18:30:15.000000', NULL, 1),
(5200050, 754881, 70514, '<td valign="top">I love lighthouses, but sometimes get tired of all the usual shots.  This is different and stunning.  Love the bit of red left.</td>', 'I love lighthouses, but sometimes get tired of all the usual shots.  This is different and stunning.  Love the bit of red left.', '2009-01-17 18:32:16.000000', NULL, 1),
(5200052, 756292, 70514, '<td valign="top">WOW!  That''s an amazing capture, stunning.</td>', 'WOW!  That''s an amazing capture, stunning.', '2009-01-17 18:32:41.000000', NULL, 1),
(5200053, 755518, 92577, '<td valign="top">fascinating (as always)</td>', 'fascinating (as always)', '2009-01-17 18:32:41.000000', NULL, 1),
(5200056, 756252, 92577, '<td valign="top">more than just photography</td>', 'more than just photography', '2009-01-17 18:33:51.000000', NULL, 1),
